begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
insert into auth.users(id) values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
insert into auth.sessions(id,user_id,created_at,updated_at) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111',now(),now()),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','22222222-2222-4222-8222-222222222222',now(),now());
create function pg_temp.c() returns jsonb language sql as $$ select '{"deviceID":"cccccccc-cccc-4ccc-8ccc-cccccccccccc","revision":1,"healthRead":true,"cloudSync":true,"aiProcessing":true,"policyVersion":"2026-09-23"}'::jsonb $$;
create function pg_temp.m(version_value int default 0,deleted_value boolean default false,mutation uuid default 'dddddddd-dddd-4ddd-8ddd-dddddddddddd') returns jsonb language sql as $$ select jsonb_build_object('id',mutation,'record',jsonb_build_object('id','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','kind','notes','logicalID','2026-09-23','payload','{"dayKey":"2026-09-23","text":"synthetic"}','version',version_value,'deleted',deleted_value)) $$;
set local role service_role;
select is(public.set_consents('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',pg_temp.c())->>'accepted','true','consent accepted');
select is(public.sync_push('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',pg_temp.m(),pg_temp.c())->'record'->>'version','1','server assigns version');
select is(public.sync_push('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',pg_temp.m(),pg_temp.c())->'record'->>'version','1','duplicate mutation does not change version');
select is(public.sync_push('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',pg_temp.m(0,false,gen_random_uuid()),pg_temp.c())->>'conflict','true','stale write conflicts');
select is(jsonb_array_length(public.sync_pull('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,pg_temp.c())->'records'),1,'pull returns one change');
select is(public.begin_ai('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','ffffffff-ffff-4fff-8fff-ffffffffffff','report',pg_temp.c())->>'accepted','true','AI request acquires slot');
select throws_ok($$select public.begin_ai('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','ffffffff-ffff-4fff-8fff-ffffffffffff','report',pg_temp.c())$$,'P0001','duplicate_request','AI retry cannot bill twice');
select throws_ok($$select public.begin_ai('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',gen_random_uuid(),'chat',pg_temp.c())$$,'P0001','request_in_progress','only one AI request in flight');
select public.finish_ai('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','ffffffff-ffff-4fff-8fff-ffffffffffff',true,'test',10,10);
do $$ declare rid uuid; begin
 for i in 1..2 loop
  rid:=gen_random_uuid();
  perform public.begin_ai('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',rid,'report',pg_temp.c());
  perform public.finish_ai('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',rid,true,'test',10,10);
 end loop;
end $$;
select throws_ok($$select public.begin_ai('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',gen_random_uuid(),'report',pg_temp.c())$$,'P0001','rate_limited','fourth daily report is rejected');
reset role;
insert into public.records(user_id,id,kind,logical_id,payload,version) values('22222222-2222-4222-8222-222222222222','12345678-1234-4234-8234-123456789012','conversations','12345678-1234-4234-8234-123456789012','{}',1);
set local role service_role;
select throws_ok($$select public.sync_push('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',jsonb_build_object('id',gen_random_uuid(),'record',jsonb_build_object('id',gen_random_uuid(),'kind','messages','logicalID','child','parentID','12345678-1234-4234-8234-123456789012','payload','{}','version',0,'deleted',false)),pg_temp.c())$$,'P0001','invalid_parent','child cannot reference another account parent');
reset role;
delete from public.records where user_id='22222222-2222-4222-8222-222222222222';
set local role service_role;
select is(public.sync_push('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',pg_temp.m(1,true,gen_random_uuid()),pg_temp.c())->'record'->>'deleted','true','deletion creates tombstone');
select is(public.sync_push('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',pg_temp.m(2,false,gen_random_uuid()),pg_temp.c())->>'conflict','true','old device cannot resurrect tombstone');
select is(public.sync_push('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',jsonb_set(pg_temp.m(0,false,gen_random_uuid()),'{record,id}',to_jsonb('99999999-9999-4999-8999-999999999999'::text)),pg_temp.c())->'record'->>'version','1','explicit restore creates a new record beside old tombstone');
select is(public.clear_cloud('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'deleted','true','clear cloud tombstones remaining records');
select is(public.sync_push('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',pg_temp.m(),pg_temp.c())->'record'->>'deleted','true','cached duplicate cannot reveal deleted payload');
select throws_ok($$select public.sync_pull('11111111-1111-4111-8111-111111111111','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',0,pg_temp.c())$$,'28000','unauthenticated','session must belong to user');
reset role;
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","session_id":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.records),0,'RLS hides other account records');
select throws_ok($$update public.records set version=9$$,'42501','permission denied for table records','client cannot forge server versions');
select throws_ok($$select public.begin_ai('22222222-2222-4222-8222-222222222222','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',gen_random_uuid(),'chat',pg_temp.c())$$,'42501','permission denied for function begin_ai','client cannot manipulate AI request states');
reset role;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","session_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);
delete from auth.sessions where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
set local role authenticated;
select throws_ok($$select * from public.records$$,'28000','unauthenticated','revoked session cannot read data');
reset role;
select * from finish();
rollback;
